import {uid} from './core.mjs';
export function createEnemyTables({getProject,commit,modal,field,esc}){
 const entriesMarkup=entries=>`<table class="enemy-entries"><thead><tr><th>몹 엔티티 ID</th><th>수량</th><th>동면</th><th></th></tr></thead><tbody>${entries.map((e,i)=>`<tr><td><input name="entity${i}" aria-label="몹 엔티티 ID ${i+1}" value="${esc(e.entity)}" required maxlength="160"></td><td><input name="count${i}" aria-label="수량 ${i+1}" type="number" min="1" max="64" value="${e.count}" required></td><td><input name="sleeping${i}" aria-label="동면 ${i+1}" type="checkbox" ${e.sleeping?'checked':''}></td><td><button type="button" class="subtle-button" data-table-row-remove="${i}" aria-label="몹 구성 ${i+1}행 삭제" ${entries.length===1?'disabled':''}>×</button></td></tr>`).join('')}</tbody></table><button type="button" class="button" data-table-row-add ${entries.length>=32?'disabled':''}>＋ 몹 종류</button>`;
 function edit(id){const old=(getProject().enemyTables||[]).find(t=>t.id===id);let entries=structuredClone(old?.entries||[{entity:'minecraft:zombie',count:1,sleeping:true}]);
  const read=()=>entries.map((e,i)=>({entity:document.querySelector(`[name=entity${i}]`).value.trim(),count:Number(document.querySelector(`[name=count${i}]`).value),sleeping:document.querySelector(`[name=sleeping${i}]`).checked}));
  modal('적 생성 테이블',field('이름','name',old?.name||'새 생성 테이블','text','required maxlength="160"')+`<div id="enemyEntries">${entriesMarkup(entries)}</div>`,data=>{const rows=read();return commit(p=>{p.enemyTables??=[];const t={...old,id:old?.id||uid('enemyTable'),name:data.get('name').trim(),entries:rows},index=p.enemyTables.findIndex(x=>x.id===t.id);if(index<0)p.enemyTables.push(t);else p.enemyTables[index]=t;});});
  document.getElementById('enemyEntries').addEventListener('click',e=>{const add=e.target.closest('[data-table-row-add]'),remove=e.target.closest('[data-table-row-remove]');if(!add&&!remove)return;entries=read();if(add&&entries.length<32)entries.push({entity:'minecraft:zombie',count:1,sleeping:true});if(remove&&entries.length>1)entries.splice(Number(remove.dataset.tableRowRemove),1);document.getElementById('enemyEntries').innerHTML=entriesMarkup(entries);});
 }
 function render(){const p=getProject();return `<div class="management-heading"><h2>적 생성 테이블</h2><button type="button" class="button primary" data-enemy-table="new">＋ 테이블</button></div><div class="management-items">${(p.enemyTables||[]).map(t=>`<article data-enemy-table-id="${esc(t.id)}"><div><strong>${esc(t.name)}</strong><small>${t.entries.map(e=>`${esc(e.entity)} × ${e.count}${e.sleeping?' · 동면':''}`).join(' / ')}</small></div><button type="button" class="button" data-enemy-table="edit" data-id="${esc(t.id)}">편집</button><button type="button" class="subtle-button" data-enemy-table="delete" data-id="${esc(t.id)}">삭제</button></article>`).join('')||'<p class="empty-state">등록된 생성 테이블 없음</p>'}</div>${p.enemyGroups?.length?`<details class="legacy-enemies"><summary>기존 생성 그룹 · ${p.enemyGroups.length}개</summary><div class="management-items">${p.enemyGroups.map(g=>`<article><div><strong>${esc(g.name)}</strong><small>${esc(g.entity)} × ${g.count}${g.enabled?' · 시작 시 자동 생성':''}</small></div><button type="button" class="button" data-manage="edit" data-id="${esc(g.id)}">기존 설정 편집</button></article>`).join('')}</div></details>`:''}`;}
 document.addEventListener('click',e=>{const b=e.target.closest('[data-enemy-table]');if(!b)return;if(b.dataset.enemyTable==='delete')return commit(p=>{p.enemyTables=p.enemyTables.filter(t=>t.id!==b.dataset.id);});edit(b.dataset.id);});
 return {render,edit};
}
